def dump(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + '\n')

def build():
    observations = json.loads(Path('/tmp/stellis-source-inspections.json').read_text())
    special = json.loads(Path('/tmp/stellis-special-inspections.json').read_text())
    observed = {x['url']: x for x in observations + special}
    refs = []
    for key, values in SOURCES.items():
        url, project, synthetic, kind, licence, layout, limitation = values
        item = observed[url]
        refs.append(dict(reference_id=key, direct_pdf_url=url, project=project, synthetic_status=synthetic, document_type=kind, licence=licence, layout=layout, limitation=limitation, role='layout', sha256=item['sha256'], verified_pdf_signature=True, inspected_all_pages=True, pages=int(re.search(r'Pages:\s+(\d+)',item['info']).group(1)), text_characters=len(item['text']), inspection_method='All-page text extraction and rendered visual review', verified_on='2026-10-23', primary_eligible=key not in {'embryology-demo','nipt-demo'}))
    dump(ROOT / 'research/reference_catalog.json', refs)
    all_inventory = []
    for x in observations:
        family = 'Original' if x['path'].startswith('PDF_Original') else 'Output example'
        layout = 'Letterhead, demographic fields, notes, visit/medication/test tables'
        if '/Easy/' in x['path']: layout += '; lavender strips and bordered/unbordered tables'
        if '/Medium/' in x['path']: layout += '; four-page encounter packet and sparse monochrome separators'
        if '/Hard/' in x['path']: layout += '; dense two-page form, moire background, binding artifacts'
        all_inventory.append(dict(project=x['project'],path=x['path'],url=x['url'],sha256=x['sha256'],pages=int(re.search(r'Pages:\s+(\d+)',x['info']).group(1)),text_characters=len(x['text']),inspection='All-page text extraction; every JSL page rendered and visually reviewed; RCA representative families visually reviewed',family=family,layout=layout))
    dump(ROOT / 'research/corpus_inspection_inventory.json',all_inventory)
    md = ['# Verified PDF references', '', 'Every original John Snow Labs PDF was downloaded and inspected: 30 Easy, 10 Medium, 10 Hard. Its 21 supplied output PDFs were also inspected. All 50 clean Root Cause Analytics PDFs were text-extracted; representative document families were rendered and visually inspected. The 27-page MyFertility sample and accepted specialty samples were inspected in full.', '', 'Primary references have explicit synthetic statements or explicit testing-account evidence. Supplemental demo reports with uncertain clinical-data provenance cannot satisfy the synthetic-reference requirement alone. Clinical recommendations come from the separate authoritative source list, not from these examples. Original PDFs, identities, logos, photographs, and wording are excluded from the archive.', '']
    for r in refs:
        md += [f"## {r['reference_id']}", '', f"Direct PDF: {r['direct_pdf_url']}", '', f"Project: {r['project']}. Type: {r['document_type']}. Pages: {r['pages']}.", '', f"Synthetic status: {r['synthetic_status']}", '', f"Layout: {r['layout']}", '', f"Use: {r['role']}. Limitation: {r['limitation']}", '', f"Reuse: {r['licence']}", '', f"Verification: HTTP download, PDF signature, all pages extracted/rendered; SHA-256 `{r['sha256']}`.", '']
    md += ['## Search outcomes', '', 'Searches covered synthetic, dummy, fictitious, demo, sample patient and sample report variants for each requested specialty, GitHub, Hugging Face, NLP/OCR datasets and laboratory/vendor test menus. Additional candidates and rejection reasons are in search_log.json. Report availability alone does not establish synthetic status.', '', 'Specialized sources found: cervical cytology test-account report, synthetic first-trimester serum screen, fertility assessment, and illustrative embryology/NIPT reports. Fully synthetic follicular-monitoring, obstetric ultrasound, delivery, and postpartum PDFs were not verified. Those entries use explicit synthetic procedural, imaging or progress-note references and disclose the specialty gap individually.', '', 'Machine-readable complete source inventory: corpus_inspection_inventory.json. Document-by-document source assignment: document_reference_inventory.json.']
    (ROOT/'research/pdf_references.md').write_text('\n'.join(md)+'\n')
    (ROOT/'research/source_licenses.md').write_text('# Source licences and reuse\n\nThe generated Maya records contain original clinical text and original renderers. Third-party PDFs, patient identities, artwork, logos and source prose are not redistributed. References inform ordinary document conventions only. No open licence is inferred from public download access.\n\n'+'\n\n'.join(f"- **{r['project']} ({r['reference_id']})**: {r['licence']} Source: {r['direct_pdf_url']}" for r in refs)+'\n\nRoot Cause Analytics attribution: Jack Webb, Synthetic Australian Medical Documents Sample, Hugging Face, 2026, CC BY-NC 4.0. This archive does not claim a commercial licence to that source. Commercial adopters should independently assess any layout-derived reuse; exact template reproduction was avoided. The new corpus and generator may be used for Stellis evaluation; source material retains its separate terms.\n')
    dump(ROOT/'research/search_log.json',[
        dict(category='cervical screening',queries=['pap smear sample report pdf dummy','cytology sample report pdf labcorp'],outcome='Accepted Labcorp 193000 test-account sample'),
        dict(category='prenatal',queries=['prenatal sample report filetype:pdf','ultrasound pregnancy DUMMY PATIENT'],outcome='Accepted Pathofast double-marker dummy report. GC Genome supplemental only.'),
        dict(category='embryology',queries=['embryology sample report','embryology report fictional','IVF report dummy pdf'],outcome='MorphIQ Jane/John/Dr Doe demonstration inspected, supplemental only; FCI Jane Doe sample identified but embryo-image provenance unverified, excluded.'),
        dict(category='ultrasound and HSG',queries=['obstetric ultrasound sample report pdf','follicular monitoring report pdf sample','ultrasound report sample fictitious','site:img.hod.report/sample-report pregnancy'],outcome='RCA fully synthetic imaging accepted as generic reference. HOD dummy sources return HTTP 403 locally. FLABS pregnancy and HSG vendor examples use inconsistent male patient header and lack explicit synthetic provenance, rejected. Astraia sample contains clinical images with unverified provenance, rejected.'),
        dict(category='delivery and postpartum',queries=['delivery discharge summary fictional pdf','postpartum discharge summary sample pdf','birth discharge summary synthetic','maternity discharge summary example filetype:pdf'],outcome='Specialized templates and quality standards found, but no verified synthetic populated PDF. Use RCA synthetic discharge and procedure references with explicit limitation.'),
        dict(category='excluded datasets',outcome='MIMIC-derived, de-identified, real case reports and transcription samples excluded; synthetic questions over real patient records do not meet this task.'),
        dict(category='other vendor samples',outcome='Dr.Lably Pap sample not accepted: real-report claim and no explicit synthetic provenance. Labcorp prenatal sample accepted after all seven pages visually reviewed; raster tables noted. Vision Chips sample TLS hostname mismatch, not verified.')])
    return refs

if __name__ == '__main__':
    build()
